WITH filtered AS (SELECT id, name, country, city, segment, signup_date, is_active, credit_limit, LENGTH(email) AS email_length, COALESCE(segment, 'UNKNOWN') AS segment_clean FROM customers WHERE signup_date > DATE '2023-08-11' AND city IS NOT NULL) SELECT s.*, latest.status, latest.account_type FROM filtered s LEFT JOIN LATERAL (SELECT c.status, c.account_type FROM accounts c WHERE c.customer_id = s.id ORDER BY c.opened_date DESC, c.id DESC LIMIT 1) latest ON TRUE
